DROP TABLE IF EXISTS `incident_coordinate_audit`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `incident_coordinate_audit` (
  `id` int NOT NULL AUTO_INCREMENT,
  `incident_id` int NOT NULL,
  `original_latitude` decimal(10,8) NOT NULL,
  `original_longitude` decimal(11,8) NOT NULL,
  `updated_latitude` decimal(10,8) NOT NULL,
  `updated_longitude` decimal(11,8) NOT NULL,
  `edited_by` int NOT NULL,
  `edited_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `reason_for_change` text NOT NULL,
  PRIMARY KEY (`id`),
  KEY `incident_id` (`incident_id`),
  KEY `edited_by` (`edited_by`),
  CONSTRAINT `incident_coordinate_audit_ibfk_1` FOREIGN KEY (`incident_id`) REFERENCES `incidents` (`id`) ON DELETE CASCADE,
  CONSTRAINT `incident_coordinate_audit_ibfk_2` FOREIGN KEY (`edited_by`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
